def _iter_between(ledger: Any, account: str, start: datetime.date, end: datetime.date):
    """Yield (date, acct, amount) entries for a date range.

    Prefers `ledger.between(start, end)` if available, but falls back to
    filtering `ledger.entries()` if needed.

    Note: The task requires using exclusive end bounds; this helper enforces
    `start <= date < end`.
    """

    try:
        entries = ledger.between(start, end - datetime.timedelta(days=1))
        # If kiln's between is inclusive on both ends, convert to exclusive-end
        # semantics by filtering anyway.
        for d, acct, amount in entries:
            if acct == account and start <= d < end:
                yield d, acct, amount
        return
    except Exception:
        pass

    for d, acct, amount in ledger.entries():
        if acct == account and start <= d < end:
            yield d, acct, amount

